command:
// ==========================================
// LUNAS WIRKUNG: MÄUSEMEISTER (APHASMA)
//
// - Fledermausleib als technische Referenz
// - genau ein gespeichertes Ziel
// - Ziel: Erwachter oder Tier
// - Größe: mittel oder kleiner
// - feste Maus aus dem Kompendium
// - Maus wird nur einmal importiert
// - bestehender Import wird wiederverwendet
// - vorübergehende Besitzerrechte
// - unverknüpfter Maustoken mit eigenen Werten
// - LeP und AeP prozentual in beide Richtungen verbunden
// - Originaltoken wird verborgen
// - automatische Rückverwandlung
// - Effekte vollständig über Block 6
// - Wirkungsende über Block 7
// - gemeinsame Karte über Block 11
// - roter GM-Button „Effekt anwenden“
// - GM benötigt kein neues Target
// ==========================================

(async function () {
const macroUuid = this?.uuid || game.macros.getName("Mäusemeister")?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden ||
    !globalThis.DSK?.Target?.Actor || !globalThis.DSK?.Wesen?.match ||
    !globalThis.DSK?.Empfaenger?.Besitzer ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor || !DSK_FW?.Wesen?.match ||
    !DSK_FW?.Empfaenger?.Besitzer ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Mäusemeister", vollerName = "Mäusemeister (Aphasma)", ahne = "Aphasma";
const mausUuid = "Compendium.dsk-core.corebestiary.Actor.BaGVz4HqAZ0QXxsi";
const flagKey = "pendingMaeusemeisterAphasma", quellFlag = "maeusemeisterMausQuelle";
const basisRechteFlag = "maeusemeisterBasisRechte", sitzungenFlag = "maeusemeisterSitzungen";
const endeKey = "aphasmaMaeusemeister";
const endeText = "Die Verwandlung endet, die Maus verschwindet und das Ziel nimmt wieder seine wahre Gestalt an.";
const erlaubteGroessen = ["tiny", "small", "average", "winzig", "klein", "mittel"];
const basisBeschreibung =
    `Das Ziel wird in eine Maus verwandelt und behält einen Teil seiner Erinnerungen.` +
    `<br><br>LeP und AeP bleiben während der Verwandlung <b>prozentual miteinander verbunden</b>.` +
    `<br><br><b>Zielkategorie:</b> Tiere und Erwachte` +
    `<br><b>Größe:</b> Mittel oder kleiner`;

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - ALLGEMEINE HELFER +++++++++++++++++++++++++++++++++++

const istAktiverGM = () => {
    const gms = game.users.filter(user => user.isGM && user.active)
        .sort((a, b) => String(a.id).localeCompare(String(b.id)));
    return gms[0] ? game.user.id === gms[0].id : game.user.isGM;
};

const begrenze = (wert, min, max) => Math.max(min, Math.min(max, Number(wert) || 0));

const liesStat = (actor, stat) => {
    const daten = foundry.utils.getProperty(actor, `system.stats.${stat}`);
    return { value: Number(daten?.value ?? 0), max: Math.max(1, Number(daten?.max ?? 1)) };
};

const prozentWert = ({ wert, maximum, zielMaximum, minimum = 0 }) => {
    const anteil = begrenze(Number(wert ?? 0) / Math.max(1, Number(maximum ?? 1)), 0, 1);
    return Math.max(minimum, Math.round(Math.max(1, Number(zielMaximum ?? 1)) * anteil));
};

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeActor = async uuid => {
    if (!uuid) return null;
    try {
        const doc = await fromUuid(uuid);
        return doc?.documentName === "Token" ? doc.actor : doc || null;
    } catch (error) {
        console.warn("Mäusemeister: Akteur konnte nicht geladen werden.", { uuid, error });
        return null;
    }
};

const ladeToken = async ({ tokenUuid = null, tokenId = null, sceneId = null } = {}) => {
    if (tokenUuid) {
        try {
            const doc = await fromUuid(tokenUuid);
            if (doc?.documentName === "Token") return doc;
        } catch (error) {
            console.warn("Mäusemeister: Token konnte nicht über UUID geladen werden.", { tokenUuid, error });
        }
    }
    return (game.scenes.get(sceneId) || canvas.scene)?.tokens.get(tokenId) || null;
};

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const findeHaupteffekt = (actor, sessionId = null) => actor?.effects?.find(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "maeusemeister") === true &&
    (!sessionId || effect.getFlag("dsk", "sessionId") === sessionId)
) || null;

const istGueltigesZiel = actor => {
    if (!actor) return false;

    const species = String(
        actor.system?.details?.species?.value ||
        actor.system?.details?.species ||
        actor.system?.species?.value || ""
    ).toLowerCase();

    const groesse = String(
        actor.system?.details?.size?.value ||
        actor.system?.details?.size ||
        actor.system?.size?.value ||
        actor.system?.size || ""
    ).toLowerCase();

    const istErwacht = DSK_FW.Wesen.match(actor, ["erwacht", "erwachter", "erwachte"]);
    const istTier = DSK_FW.Wesen.match(actor, ["tier", "tiere"]) || species.includes("tier");
    const groesseErlaubt = !groesse || erlaubteGroessen.some(wert => groesse.includes(wert));

    return (istErwacht || istTier) && groesseErlaubt;
};

// +++ 4 - MAUS IMPORTIEREN ++++++++++++++++++++++++++++++++++++

const findeImportierteMaus = () => game.actors.find(actor =>
    actor.getFlag("dsk", quellFlag) === mausUuid ||
    actor.getFlag("core", "sourceId") === mausUuid
) || null;

const ladeOderImportiereMaus = async () => {
    let mausActor = findeImportierteMaus();

    if (mausActor) {
        if (mausActor.getFlag("dsk", quellFlag) !== mausUuid) {
            await mausActor.setFlag("dsk", quellFlag, mausUuid);
        }
        return mausActor;
    }

    const kompendiumActor = await fromUuid(mausUuid);
    if (!kompendiumActor) throw new Error(`Maus nicht gefunden: ${mausUuid}`);

    const daten = kompendiumActor.toObject();
    delete daten._id;
    delete daten.folder;
    delete daten.sort;

    foundry.utils.setProperty(daten, `flags.dsk.${quellFlag}`, mausUuid);
    foundry.utils.setProperty(daten, "flags.core.sourceId", mausUuid);

    mausActor = await Actor.create(daten, { renderSheet: false });
    if (!mausActor) throw new Error("Der Maus-Akteur konnte nicht importiert werden.");
    return mausActor;
};

// +++ 5 - RECHTEVERWALTUNG ++++++++++++++++++++++++++++++++++++

const baueRechte = ({ basis = {}, sitzungen = {} }) => {
    const ownership = foundry.utils.deepClone(basis);

    for (const sitzung of Object.values(sitzungen)) {
        for (const userId of sitzung?.userIds || []) {
            if (game.users.get(userId)) ownership[userId] = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
        }
    }

    return ownership;
};

const fuegeRechteHinzu = async ({ mausActor, sessionId, userIds }) => {
    const sitzungen = foundry.utils.deepClone(mausActor.getFlag("dsk", sitzungenFlag) || {});
    let basis = mausActor.getFlag("dsk", basisRechteFlag);

    if (!basis || !Object.keys(sitzungen).length) {
        basis = foundry.utils.deepClone(mausActor.ownership || {});
    }

    sitzungen[sessionId] = { userIds: [...new Set(userIds)], erstellt: Date.now() };

    await mausActor.update({
        ownership: baueRechte({ basis, sitzungen }),
        [`flags.dsk.${quellFlag}`]: mausUuid,
        [`flags.dsk.${basisRechteFlag}`]: basis,
        [`flags.dsk.${sitzungenFlag}`]: sitzungen
    });
};

const entferneRechte = async ({ mausActor, sessionId }) => {
    if (!mausActor || !sessionId) return false;

    const sitzungen = foundry.utils.deepClone(mausActor.getFlag("dsk", sitzungenFlag) || {});
    const basis = mausActor.getFlag("dsk", basisRechteFlag);
    delete sitzungen[sessionId];

    if (!Object.keys(sitzungen).length) {
        await mausActor.update({
            ownership: foundry.utils.deepClone(basis || mausActor.ownership || {})
        });

        if (mausActor.getFlag("dsk", basisRechteFlag) !== undefined) {
            await mausActor.unsetFlag("dsk", basisRechteFlag);
        }
        if (mausActor.getFlag("dsk", sitzungenFlag) !== undefined) {
            await mausActor.unsetFlag("dsk", sitzungenFlag);
        }
        return true;
    }

    await mausActor.update({
        ownership: baueRechte({
            basis: basis || mausActor.ownership || {},
            sitzungen
        }),
        [`flags.dsk.${sitzungenFlag}`]: sitzungen
    });

    return true;
};

// +++ 6 - MAUSTOKEN ERZEUGEN ++++++++++++++++++++++++++++++++++

const erzeugeMausToken = async ({ originalActor, originalToken, mausActor, sessionId }) => {
    const tokenDoc = originalToken.document || originalToken;
    const originalLeP = liesStat(originalActor, "LeP");
    const originalAeP = liesStat(originalActor, "AeP");
    const mausLeP = liesStat(mausActor, "LeP");
    const mausAeP = liesStat(mausActor, "AeP");

    const startLeP = prozentWert({
        wert: originalLeP.value, maximum: originalLeP.max,
        zielMaximum: mausLeP.max, minimum: originalLeP.value > 0 ? 1 : 0
    });

    const startAeP = prozentWert({
        wert: originalAeP.value, maximum: originalAeP.max,
        zielMaximum: mausAeP.max, minimum: 0
    });

    const vorlage = await mausActor.getTokenDocument({
        x: tokenDoc.x, y: tokenDoc.y,
        elevation: tokenDoc.elevation || 0,
        hidden: false, actorLink: false
    });

    if (!vorlage) throw new Error("Die Maus-Tokenvorlage konnte nicht erzeugt werden.");

    const daten = vorlage.toObject();
    delete daten._id;

    Object.assign(daten, {
        x: tokenDoc.x, y: tokenDoc.y,
        elevation: tokenDoc.elevation || 0,
        hidden: false, actorId: mausActor.id, actorLink: false,
        disposition: tokenDoc.disposition,
        displayName: tokenDoc.displayName,
        displayBars: tokenDoc.displayBars
    });

    daten.delta = foundry.utils.deepClone(daten.delta || {});

    foundry.utils.setProperty(daten, "delta.system.stats.LeP.value", startLeP);
    foundry.utils.setProperty(daten, "delta.system.stats.AeP.value", startAeP);
    foundry.utils.setProperty(daten, "delta.flags.dsk.maeusemeisterMaus", true);
    foundry.utils.setProperty(daten, "delta.flags.dsk.isMausVon", originalActor.uuid);
    foundry.utils.setProperty(daten, "delta.flags.dsk.maeusemeisterSessionId", sessionId);

    foundry.utils.setProperty(daten, "flags.dsk.maeusemeisterMaus", true);
    foundry.utils.setProperty(daten, "flags.dsk.isMausVon", originalActor.uuid);
    foundry.utils.setProperty(daten, "flags.dsk.maeusemeisterSessionId", sessionId);
    foundry.utils.setProperty(daten, "flags.dsk.originalTokenUuid", tokenDoc.uuid);

    const [mausToken] = await canvas.scene.createEmbeddedDocuments("Token", [daten]);

    if (!mausToken?.actor) {
        if (mausToken) {
            await canvas.scene.deleteEmbeddedDocuments(
                "Token", [mausToken.id], { dskMaeusemeisterCleanup: true }
            ).catch(() => {});
        }
        throw new Error("Der synthetische Maus-Akteur konnte nicht erzeugt werden.");
    }

    await mausToken.actor.update({
        "system.stats.LeP.value": startLeP,
        "system.stats.AeP.value": startAeP,
        "flags.dsk.maeusemeisterMaus": true,
        "flags.dsk.isMausVon": originalActor.uuid,
        "flags.dsk.maeusemeisterSessionId": sessionId
    }, { dskMaeusemeisterSetup: true });

    return mausToken;
};

// +++ 7 - RÜCKVERWANDLUNG +++++++++++++++++++++++++++++++++++++

const rueckverwandeln = async effect => {
    if (!effect || !istAktiverGM() || effect.getFlag("dsk", "maeusemeister") !== true) return false;

    const originalActor = effect.parent;
    if (!originalActor) return false;

    const sceneId = effect.getFlag("dsk", "sceneId");
    const originalTokenUuid = effect.getFlag("dsk", "originalTokenUuid");
    const originalTokenId = effect.getFlag("dsk", "originalTokenId");
    const originalWarVerborgen = effect.getFlag("dsk", "originalWarVerborgen") === true;
    const mausTokenUuid = effect.getFlag("dsk", "mausTokenUuid");
    const mausTokenId = effect.getFlag("dsk", "mausTokenId");
    const mausActorUuid = effect.getFlag("dsk", "mausActorUuid");
    const sessionId = effect.getFlag("dsk", "sessionId");
    const scene = game.scenes.get(sceneId) || canvas.scene;

    const mausToken = await ladeToken({
        tokenUuid: mausTokenUuid,
        tokenId: mausTokenId,
        sceneId
    });

    const mausTokenActor = mausToken?.actor || null;

    if (mausTokenActor) {
        const mausLeP = liesStat(mausTokenActor, "LeP");
        const mausAeP = liesStat(mausTokenActor, "AeP");
        const originalLeP = liesStat(originalActor, "LeP");
        const originalAeP = liesStat(originalActor, "AeP");

        const update = {
            "system.stats.LeP.value": prozentWert({
                wert: mausLeP.value, maximum: mausLeP.max,
                zielMaximum: originalLeP.max, minimum: mausLeP.value > 0 ? 1 : 0
            })
        };

        if (mausTokenActor.system?.stats?.AeP && originalActor.system?.stats?.AeP) {
            update["system.stats.AeP.value"] = prozentWert({
                wert: mausAeP.value, maximum: mausAeP.max,
                zielMaximum: originalAeP.max, minimum: 0
            });
        }

        await originalActor.update(update, { dskMaeusemeisterSync: true });
    }

    const originalToken = await ladeToken({
        tokenUuid: originalTokenUuid,
        tokenId: originalTokenId,
        sceneId
    });

    if (originalToken) await originalToken.update({ hidden: originalWarVerborgen });

    if (scene && mausTokenId && scene.tokens.get(mausTokenId)) {
        await scene.deleteEmbeddedDocuments(
            "Token", [mausTokenId], { dskMaeusemeisterCleanup: true }
        );
    }

    let mausActor = await ladeActor(mausActorUuid);
    if (!mausActor) mausActor = findeImportierteMaus();
    if (mausActor && sessionId) await entferneRechte({ mausActor, sessionId });

    return true;
};

// +++ 8 - WÄCHTER +++++++++++++++++++++++++++++++++++++++++++++

if (globalThis._dskMaeusemeisterUpdateHook) {
    Hooks.off("updateActor", globalThis._dskMaeusemeisterUpdateHook);
}

globalThis._dskMaeusemeisterUpdateHook = Hooks.on(
    "updateActor",
    async (updatedActor, changes, options) => {
        if (
            !istAktiverGM() ||
            options?.dskMaeusemeisterSync ||
            options?.dskMaeusemeisterSetup
        ) return;

        const lePChange = foundry.utils.getProperty(changes, "system.stats.LeP.value");
        const aePChange = foundry.utils.getProperty(changes, "system.stats.AeP.value");
        if (lePChange === undefined && aePChange === undefined) return;

        const originalUuid = updatedActor.getFlag("dsk", "isMausVon");

        // Maus → ursprünglicher Akteur
        if (originalUuid) {
            const originalActor = await ladeActor(originalUuid);
            if (!originalActor) return;

            const update = {};

            if (lePChange !== undefined) {
                const mausLeP = liesStat(updatedActor, "LeP");
                const originalLeP = liesStat(originalActor, "LeP");

                update["system.stats.LeP.value"] = prozentWert({
                    wert: lePChange, maximum: mausLeP.max,
                    zielMaximum: originalLeP.max, minimum: Number(lePChange) > 0 ? 1 : 0
                });
            }

            if (
                aePChange !== undefined &&
                updatedActor.system?.stats?.AeP &&
                originalActor.system?.stats?.AeP
            ) {
                const mausAeP = liesStat(updatedActor, "AeP");
                const originalAeP = liesStat(originalActor, "AeP");

                update["system.stats.AeP.value"] = prozentWert({
                    wert: aePChange, maximum: mausAeP.max,
                    zielMaximum: originalAeP.max, minimum: 0
                });
            }

            if (Object.keys(update).length) {
                await originalActor.update(update, { dskMaeusemeisterSync: true });
            }
            return;
        }

        // Ursprünglicher Akteur → Maus
        const effekt = findeHaupteffekt(updatedActor);
        if (!effekt) return;

        const mausToken = await ladeToken({
            tokenUuid: effekt.getFlag("dsk", "mausTokenUuid"),
            tokenId: effekt.getFlag("dsk", "mausTokenId"),
            sceneId: effekt.getFlag("dsk", "sceneId")
        });

        const mausTokenActor = mausToken?.actor;
        if (!mausTokenActor) return;

        const update = {};

        if (lePChange !== undefined) {
            const originalLeP = liesStat(updatedActor, "LeP");
            const mausLeP = liesStat(mausTokenActor, "LeP");

            update["system.stats.LeP.value"] = prozentWert({
                wert: lePChange, maximum: originalLeP.max,
                zielMaximum: mausLeP.max, minimum: Number(lePChange) > 0 ? 1 : 0
            });
        }

        if (
            aePChange !== undefined &&
            updatedActor.system?.stats?.AeP &&
            mausTokenActor.system?.stats?.AeP
        ) {
            const originalAeP = liesStat(updatedActor, "AeP");
            const mausAeP = liesStat(mausTokenActor, "AeP");

            update["system.stats.AeP.value"] = prozentWert({
                wert: aePChange, maximum: originalAeP.max,
                zielMaximum: mausAeP.max, minimum: 0
            });
        }

        if (Object.keys(update).length) {
            await mausTokenActor.update(update, { dskMaeusemeisterSync: true });
        }
    }
);

if (globalThis._dskMaeusemeisterDeleteEffectHook) {
    Hooks.off("deleteActiveEffect", globalThis._dskMaeusemeisterDeleteEffectHook);
}

globalThis._dskMaeusemeisterDeleteEffectHook = Hooks.on(
    "deleteActiveEffect",
    async effect => {
        if (!istAktiverGM()) return;

        try {
            await rueckverwandeln(effect);
        } catch (error) {
            console.error("Mäusemeister: Rückverwandlung fehlgeschlagen.", error);
        }
    }
);

if (globalThis._dskMaeusemeisterDeleteTokenHook) {
    Hooks.off("deleteToken", globalThis._dskMaeusemeisterDeleteTokenHook);
}

globalThis._dskMaeusemeisterDeleteTokenHook = Hooks.on(
    "deleteToken",
    async (tokenDokument, options) => {
        if (
            !istAktiverGM() ||
            options?.dskMaeusemeisterCleanup ||
            tokenDokument.getFlag("dsk", "maeusemeisterMaus") !== true
        ) return;

        const originalUuid = tokenDokument.getFlag("dsk", "isMausVon");
        const sessionId = tokenDokument.getFlag("dsk", "maeusemeisterSessionId");
        const originalActor = await ladeActor(originalUuid);

        if (originalActor) {
            const effekt = findeHaupteffekt(originalActor, sessionId);
            if (effekt) {
                await effekt.delete();
                return;
            }
        }

        const mausActor = game.actors.get(tokenDokument.actorId) || findeImportierteMaus();
        if (mausActor && sessionId) await entferneRechte({ mausActor, sessionId });
    }
);

// +++ 9 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !istAktiverGM()) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(
        casterActor,
        daten.casterTokenId,
        daten.casterTokenUuid
    );

    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const { token: targetToken, actor: targetActor } = await ladeZiel(daten.target);
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
    const dauerMinuten = qs;

    if (!targetToken || !targetActor || !istGueltigesZiel(targetActor)) {
        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
            wirkender: casterName, ziele: [], misserfolge: [{ name: targetName }],
            dauerText: `${dauerMinuten} Minuten`, erfolgreich: false
        });
        return true;
    }

    const vorhandenerEffekt = findeHaupteffekt(targetActor);

    if (vorhandenerEffekt) {
        ui.notifications.warn(`Luna sagt 🌙: ${targetName} ist bereits in eine Maus verwandelt!`);
        return false;
    }

    const sessionId = `maeusemeister-${Date.now()}-${foundry.utils.randomID()}`;
    const originalTokenDoc = targetToken.document || targetToken;
    const originalWarVerborgen = originalTokenDoc.hidden === true;

    let mausActor = null;
    let mausToken = null;
    let originalVersteckt = false;
    let erzeugterEffekt = null;
    let mausEffekt = null;

    try {
        mausActor = await ladeOderImportiereMaus();

        const userIds = new Set([
            ...DSK_FW.Empfaenger.Besitzer(casterActor),
            ...DSK_FW.Empfaenger.Besitzer(targetActor)
        ]);

        if (daten.requestedByUserId && game.users.get(daten.requestedByUserId)) {
            userIds.add(daten.requestedByUserId);
        }

        await fuegeRechteHinzu({
            mausActor,
            sessionId,
            userIds: [...userIds]
        });

        mausToken = await erzeugeMausToken({
            originalActor: targetActor,
            originalToken: targetToken,
            mausActor,
            sessionId
        });

        await originalTokenDoc.update({ hidden: true });
        originalVersteckt = true;

        const beschreibung =
            `<b>${targetName}</b> wurde von <b>${casterName}</b> in eine Maus verwandelt.` +
            `<br><br>LeP und AeP bleiben prozentual mit dem ursprünglichen Körper verbunden.` +
            `<br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`;

        erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne, beschreibung,
            gabeZiel: "", qs, ziel: targetActor,
            changes: [{
                key: "flags.dsk.status",
                mode: CONST.ACTIVE_EFFECT_MODES.OVERRIDE,
                value: "In eine Maus verwandelt",
                priority: 20
            }],
            duration: {
                seconds: dauerMinuten * 60,
                startTime: game.time.worldTime
            },
            origin: casterActor.uuid,
            showIcon: 1,
            flags: {
                core: { statusId: "maeusemeister-wandlung" },
                dsk: {
                    maeusemeister: true,
                    casterUuid: casterActor.uuid,
                    qs,
                    sceneId: canvas.scene.id,
                    originalTokenUuid: originalTokenDoc.uuid,
                    originalTokenId: originalTokenDoc.id,
                    originalWarVerborgen,
                    mausActorUuid: mausActor.uuid,
                    mausActorId: mausActor.id,
                    mausTokenUuid: mausToken.uuid,
                    mausTokenId: mausToken.id,
                    sessionId,
                    requestedByUserId: daten.requestedByUserId || null,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!erzeugterEffekt) {
            throw new Error("Der Mäusemeister-Effekt konnte nicht erstellt werden.");
        }

        mausEffekt = await DSK_FW.Effekt.Anwenden({
            name: `${vollerName} – Verwandlung`,
            ahne,
            beschreibung: `Diese Maus ist in Wahrheit <b>${targetName}</b>.`,
            gabeZiel: "", qs, ziel: mausToken.actor,
            showIcon: 1,
            flags: {
                dsk: {
                    isMaeusemeisterMausEffekt: true,
                    casterUuid: casterActor.uuid,
                    originalActorUuid: targetActor.uuid,
                    sessionId,
                    sourceEffectUuid: erzeugterEffekt.uuid
                }
            }
        });

        if (!mausEffekt) {
            throw new Error("Der Verwandlungseffekt auf der Maus konnte nicht angelegt werden.");
        }

        const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");
        const quelleKorrekt =
            erzeugterEffekt.getFlag("dsk", "maeusemeister") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            erzeugterEffekt.getFlag("dsk", "sessionId") === sessionId &&
            erzeugterEffekt.getFlag("dsk", "mausTokenId") === mausToken.id &&
            endeDaten?.sfName === endeKey &&
            endeDaten?.basisEffektName === vollerName;

        const mausKorrekt =
            mausEffekt.getFlag("dsk", "isMaeusemeisterMausEffekt") === true &&
            mausEffekt.getFlag("dsk", "originalActorUuid") === targetActor.uuid &&
            mausEffekt.getFlag("dsk", "sessionId") === sessionId;

        if (!quelleKorrekt || !mausKorrekt) {
            throw new Error("Die Mäusemeister-Verknüpfung wurde nicht vollständig angelegt.");
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
            wirkender: casterName,
            ziele: [{ name: targetName, rolle: "In eine Maus verwandelt" }],
            misserfolge: [],
            dauerText: `${dauerMinuten} Minuten (${qs} QS × 1 Min.)`,
            erfolgreich: true
        });

        ui.notifications.info(`Luna sagt 🌙: ${targetName} wurde in eine Maus verwandelt.`);
        return true;

    } catch (error) {
        console.error("Mäusemeister: Verwandlung fehlgeschlagen.", error);

        if (mausEffekt) {
            await mausEffekt.delete().catch(() => {});
        }

        if (erzeugterEffekt) {
            await erzeugterEffekt.delete().catch(() => {});
        }

        if (originalVersteckt) {
            await originalTokenDoc.update({ hidden: originalWarVerborgen }).catch(() => {});
        }

        if (mausToken && canvas.scene?.tokens.get(mausToken.id)) {
            await canvas.scene.deleteEmbeddedDocuments(
                "Token", [mausToken.id], { dskMaeusemeisterCleanup: true }
            ).catch(() => {});
        }

        if (mausActor && sessionId) {
            await entferneRechte({ mausActor, sessionId }).catch(() => {});
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
            wirkender: casterName, ziele: [],
            misserfolge: [{ name: targetName }],
            dauerText: `${dauerMinuten} Minuten`,
            erfolgreich: false
        }).catch(() => {});

        ui.notifications.error(
            `Luna sagt 🌙: Die Verwandlung konnte nicht vollständig durchgeführt werden: ${error?.message || error}`
        );

        return true;
    }
};

// +++ 10 - GM-MODUS +++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }
        return;
    }
}

// +++ 11 - WIRKENDER UND QS +++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Mäusemeister Probe", "Mäusemeister"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die Verwandlung konnte nicht eingeleitet werden.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten",
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 12 - GENAU EIN ZIEL PRÜFEN ++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);

if (targets.length !== 1) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau ein Ziel für die Verwandlung!");
}

const targetToken = targets[0];
const targetActor = targetToken?.actor;
const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

if (
    !targetActor ||
    targetActor.uuid === casterActor.uuid ||
    targetActor.id === casterActor.id ||
    !istGueltigesZiel(targetActor)
) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: targetName }],
        dauerText: `${qs} Minuten`,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

if (findeHaupteffekt(targetActor)) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn(`Luna sagt 🌙: ${targetName} ist bereits in eine Maus verwandelt!`);
}

const targetDaten = DSK_FW.Target.Merken(targetToken);

if (!targetDaten) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!");
}

// +++ 13 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++++++

const dauerText = `${qs} Minuten (${qs} QS × 1 Min.)`;

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
    wirkender: casterName,
    ziele: [{ name: targetName, rolle: "Zu verwandelndes Ziel" }],
    misserfolge: [],
    dauerText, gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    target: targetDaten,
    qs,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

// +++ 14 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);

ui.notifications.info(
    "Luna sagt 🌙: Mäusemeister wurde bei der Spielleitung zur Anwendung beantragt."
);

}).call(this);
